        assertEquals(Boolean.FALSE, mapper.readValue("\"abc\"", Boolean.TYPE));
        assertArrayEquals(new byte[] { 1, 0 }, mapper.readValue("[1,\"abc\"]", byte[].class));
        assertArrayEquals(new short[] { 1, 0 }, mapper.readValue("[1,\"abc\"]", short[].class));

